/* Driver for tests/fixtures/verify_original_economy.py. Synthetic complete saves
 * are generated by the original-execution harness, not bundled game data. */
#include "mercseconomy.h"
#include <stdio.h>
#include <stdlib.h>

int main(int argc,char **argv)
{
    FILE *f;long length;uint8_t *input,*output;size_t written;mercs_save_state *s=NULL;
    int kind,buy,rc;size_t index;
    if(argc!=6)return 20;
    kind=atoi(argv[1]);buy=atoi(argv[2]);index=(size_t)strtoul(argv[3],NULL,10);
    f=fopen(argv[4],"rb");if(!f)return 21;
    fseek(f,0,SEEK_END);length=ftell(f);rewind(f);if(length<0){fclose(f);return 22;}
    input=malloc((size_t)length);if(!input){fclose(f);return 23;}
    if(fread(input,1,(size_t)length,f)!=(size_t)length){fclose(f);free(input);return 24;}
    fclose(f);rc=mercs_save_decode(input,(size_t)length,&s);free(input);if(rc)return 25;
    if(kind==8){int viable=-1;rc=mercs_economy_viable(s,&viable);printf("%d\n",viable);}
    else rc=kind==7?mercs_economy_weapon_group(s,index,buy):kind==5?mercs_economy_cycle_pilot(s,index,buy?1:-1):
        kind==6?mercs_economy_toggle_aerotech(s,index):kind==4?mercs_economy_trade_mech(s,buy,index):kind<2?mercs_economy_trade_item(s,kind,buy,index):
        buy?mercs_economy_hire(s,(enum mercs_personnel_kind)(kind-2),index):
        mercs_economy_dismiss(s,(enum mercs_personnel_kind)(kind-2),index);
    if(mercs_save_encode(s,1,&output,&written)){mercs_save_free(s);return 26;}
    mercs_save_free(s);f=fopen(argv[5],"wb");if(!f){free(output);return 27;}
    if(fwrite(output,1,written,f)!=written){fclose(f);free(output);return 28;}
    fclose(f);free(output);return rc? -rc:0;
}
